// The compact FastOp tier is ordinary, statically linked C++ code.  It is
// therefore available to both macOS and iOS Apple-ARM64 builds without JIT
// pages, while focused CPU tests retain the same semantic path on every host.
// Production diagnostic binaries stay on the canonical dispatcher so their
// event stream remains comparable; the CPU test target keeps an explicit seam.
#if defined(LUMEN_CPU_X64_TEST) || \
    (defined(__APPLE__) && defined(__aarch64__) && defined(NDEBUG) && \
     !defined(LUMEN_FAST_BLOCK_TELEMETRY) && \
     !defined(LUMEN_A64_DYNAREC_TELEMETRY) && \
     !defined(LUMEN_A64_DYNAREC_STARTUP_TELEMETRY) && \
     !defined(LUMEN_A64_DYNAREC_PHASE6AF_TELEMETRY) && \
     !defined(LUMEN_A64_DYNAREC_PHASE6AL_TELEMETRY) && \
     !defined(LUMEN_A64_DYNAREC_CROSS_OWNER_TELEMETRY) && \
     !defined(LUMEN_A64_DYNAREC_HOST_PC_PROFILE) && \
     !defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE) && \
     !defined(LUMEN_A64_DYNAREC_PHASE6CM_PROFILE) && \
     !defined(LUMEN_A64_DYNAREC_PHASE6CO_PROFILE) && \
     !defined(LUMEN_A64_DYNAREC_RFLAGS_PROFILE) && \
     !defined(LUMEN_A64_DYNAREC_GPR_CACHE_PROFILE))
#define LUMEN_X64_A64_COMPACT_FASTOP_TIER_COMPILED 1
#else
#define LUMEN_X64_A64_COMPACT_FASTOP_TIER_COMPILED 0
#endif

#if !LUMEN_X64_A64_REJECTED_FASTBLOCK_PURGE_COMPILED
// Non-purge builds retain the rejected candidates for focused tests and old
// artifact reproduction. Keep their decisions in one register argument.
constexpr uint8_t FAST_BLOCK_CANDIDATE_POLICY_UFSB = 1u << 0;
constexpr uint8_t FAST_BLOCK_CANDIDATE_POLICY_IMSE = 1u << 1;
constexpr uint8_t FAST_BLOCK_CANDIDATE_POLICY_CALLBACK_FREE_ORDINARY_SPECIALIZATION =
    1u << 2;
static_assert((FAST_BLOCK_CANDIDATE_POLICY_UFSB &
               FAST_BLOCK_CANDIDATE_POLICY_IMSE) == 0);
static_assert(
    (FAST_BLOCK_CANDIDATE_POLICY_CALLBACK_FREE_ORDINARY_SPECIALIZATION &
     (FAST_BLOCK_CANDIDATE_POLICY_UFSB |
      FAST_BLOCK_CANDIDATE_POLICY_IMSE)) == 0);
#endif

