[[maybe_unused]] bool
FastBlockInlineFixedSignatureMatchEnvironmentValueEnabled(const char* value)
{
	// This candidate changes only how the three live dispatcher checks are
	// emitted. Exact one opts in; every other spelling keeps the historical
	// fixed-chunk matching semantics (the optimizer may still inline it).
	return value != nullptr && std::strcmp(value, "1") == 0;
}

[[maybe_unused]] bool
FastBlockUnrolledFixedSignatureBatchingEnvironmentValueEnabled(
	const char* value)
{
	// The selector refines only the retained IFSM implementation. Exact one is
	// the sole opt-in; every other spelling leaves IFSM byte-for-byte reachable.
	return value != nullptr && std::strcmp(value, "1") == 0;
}

[[maybe_unused]] bool
FastBlockIdempotentMruStoreElisionEnvironmentValueEnabled(const char* value)
{
	// Only exact one opts into the conditional TLS store. Absent, zero and
	// malformed values preserve all four historical MRU assignments.
	return value != nullptr && std::strcmp(value, "1") == 0;
}

[[maybe_unused]] bool
FastBlockCallbackFreeOrdinarySpecializationEnvironmentValueEnabled(
	const char* value)
{
	// Exact one selects the proof-gated ordinary specialization. Every other
	// spelling retains the historical snapshot and diagnostic branches.
	return value != nullptr && std::strcmp(value, "1") == 0;
}

[[maybe_unused]] bool
A64CompactFastOpTierEnvironmentValueEnabled(const char* value)
{
	// The compact tier changes the ordinary FastOp dispatch body. Exact one is
	// the sole opt-in; absent, zero and malformed values retain the canonical
	// switch, including on Apple ARM64 no-JIT targets.
	return value != nullptr && std::strcmp(value, "1") == 0;
}

[[maybe_unused]] bool
ArmLoadingCompositeReceiptEnvironmentValueEnabled(const char* value)
{
	// This selector is a fail-closed receipt only. The optimization itself is a
	// build-time text-layout change, because retaining a runtime rollback would
	// also retain the rejected code and invalidate the measurement.
	return value != nullptr && std::strcmp(value, "1") == 0;
}

