struct A64DynarecNativeOnlyAdmissionSelection
{
	bool requested = false;
	bool strict_coverage = false;
};

const A64DynarecNativeOnlyAdmissionSelection&
A64DynarecNativeOnlyAdmissionSelectionForProcess()
{
#if defined(__APPLE__) && defined(__aarch64__) && TARGET_OS_OSX && \
    !TARGET_OS_IPHONE && \
    !defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_PHASE6CM_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_PHASE6CO_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_RFLAGS_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_GPR_CACHE_PROFILE)
	// Routing and coverage strictness are one process contract. The promoted
	// absent-selector default enables routing without imposing WMD-specific
	// coverage on every game; exact one preserves the strict historical g5 gate.
	static const A64DynarecNativeOnlyAdmissionSelection selection = []()
	{
		const char* value = std::getenv(
		    "LUMEN_X64_A64_DYNAREC_NATIVE_ONLY_ADMISSION");
		bool default_enabled =
		    LUMEN_X64_A64_RETAINED_FASTPATH_DEFAULT_ENABLED != 0;
#if defined(LUMEN_CPU_X64_TEST)
		if (g_a64_dynarec_test_native_only_admission_default_override >= 0)
		{
			default_enabled =
			    g_a64_dynarec_test_native_only_admission_default_override != 0;
		}
#endif
		return A64DynarecNativeOnlyAdmissionSelection {
		    A64DynarecNativeOnlyAdmissionEnvironmentValueEnabledWithDefault(
		        value, default_enabled),
		    value != nullptr && std::strcmp(value, "1") == 0};
	}();
#elif defined(__ANDROID__) && defined(__aarch64__) && \
    defined(LUMEN_ANDROID_DYNAREC_POLICY_SELECTIVE_NODA)
	// Android has no promoted default: the compile-time policy and the exact
	// runtime selector must both opt in. Coverage remains non-strict because
	// the startup self-test and per-entry oracle are the Android correctness
	// gates; macOS-specific WMD coverage is not portable to this build.
	static const A64DynarecNativeOnlyAdmissionSelection selection = []()
	{
		const char* value = std::getenv(
		    "LUMEN_X64_A64_DYNAREC_NATIVE_ONLY_ADMISSION");
		return A64DynarecNativeOnlyAdmissionSelection {
		    value != nullptr && std::strcmp(value, "1") == 0, false};
	}();
#else
	static constexpr A64DynarecNativeOnlyAdmissionSelection selection {};
#endif
	return selection;
}

bool A64DynarecNativeOnlyAdmissionRequested()
{
	return A64DynarecNativeOnlyAdmissionSelectionForProcess().requested;
}

bool A64DynarecNativeOnlyAdmissionStrictCoverageRequested()
{
	return A64DynarecNativeOnlyAdmissionSelectionForProcess().strict_coverage;
}

bool FastBlockNoJitOperationSnapshotElisionRequested()
{
#if defined(__APPLE__) && defined(__aarch64__)
	// This independent, process-latched opt-in extends the existing ownership
	// proof to the static C++ executor on macOS and iOS. It cannot request a
	// dynarec, and absent/zero/malformed values preserve the no-JIT copy path.
	static const bool requested =
	    A64DynarecGuestMemoryOperationSnapshotElisionEnvironmentValueEnabled(
	        std::getenv("LUMEN_X64_FAST_BLOCK_NOJIT_SNAPSHOT_ELISION"));
	return requested;
#else
	return false;
#endif
}

bool A64DynarecGuestMemoryOperationSnapshotElisionRequested()
{
#if defined(__APPLE__) && defined(__aarch64__) && TARGET_OS_OSX && !TARGET_OS_IPHONE
	// The selector and every FastBlock proof that it authorizes are one process
	// contract. Nested Runs must not be able to reinterpret a live proof.
	static const bool requested =
	    A64RetainedFastPathEnvironmentValueEnabled(
	        std::getenv(
	            "LUMEN_X64_A64_DYNAREC_GUEST_MEMORY_OPERATION_SNAPSHOT_ELISION"));
	return requested;
#elif defined(__ANDROID__) && defined(__aarch64__) && \
    defined(LUMEN_ANDROID_DYNAREC_PROVIDER_DISABLED) && \
    defined(LUMEN_ANDROID_ARM_FASTBLOCK_SNAPSHOT_ELISION)
	// The Android full runtime uses the same static C++ FastBlock executor and
	// NonReentrant contextual translator proof as phase-6CP. This build-time
	// selector changes only operation-prefix ownership; it does not enable the
	// Android dynarec provider, JIT pages or guest-native execution.
	return true;
#else
	return false;
#endif
}

