[[maybe_unused]] constexpr uint8_t
    FAST_BLOCK_CALLBACK_FREE_ORDINARY_REENTRY_SAFE_COVERAGE =
    1u << 0;
[[maybe_unused]] constexpr uint8_t
    FAST_BLOCK_CALLBACK_FREE_ORDINARY_SNAPSHOT_ELISION_COVERAGE =
    1u << 1;

[[maybe_unused]] void RecordFastBlockCallbackFreeOrdinarySpecializationCoverage(
	X64ThreadContext& context, bool execution_reentry_safe)
{
#if LUMEN_X64_A64_FAST_BLOCK_CALLBACK_FREE_ORDINARY_SPECIALIZATION_COMPILED
	const uint8_t coverage =
	    execution_reentry_safe
	        ? FAST_BLOCK_CALLBACK_FREE_ORDINARY_REENTRY_SAFE_COVERAGE
	        : FAST_BLOCK_CALLBACK_FREE_ORDINARY_SNAPSHOT_ELISION_COVERAGE;
	if ((context.fast_block_callback_free_ordinary_specialization_coverage &
	     coverage) != 0)
		return;
	if (execution_reentry_safe)
	{
		g_fast_block_callback_free_ordinary_specialization_telemetry.reentry_safe.store(
		    true, std::memory_order_release);
	}
	else
	{
		g_fast_block_callback_free_ordinary_specialization_telemetry.snapshot_elision.store(
		    true, std::memory_order_release);
	}
	context.fast_block_callback_free_ordinary_specialization_coverage |= coverage;
#else
	(void)context;
	(void)execution_reentry_safe;
#endif
}

enum class FastBlockMruStoreSite : uint8_t
{
	SuccessorHit,
	DenseHit,
	HistoricalHit,
	Victim,
	Count,
};

#if defined(LUMEN_CPU_X64_TEST)
thread_local uint64_t g_fast_block_test_mru_stores[
    static_cast<size_t>(FastBlockMruStoreSite::Count)] {};
thread_local uint64_t g_fast_block_test_mru_elisions[
    static_cast<size_t>(FastBlockMruStoreSite::Count)] {};
#endif

[[maybe_unused]] void
RecordFastBlockIdempotentMruStoreElision(X64ThreadContext& context)
{
#if LUMEN_X64_A64_FAST_BLOCK_IDEMPOTENT_MRU_STORE_ELISION_COMPILED
	if (context.fast_block_idempotent_mru_store_elision_published) return;
	g_fast_block_idempotent_mru_store_elision_telemetry.elided.store(
	    true, std::memory_order_release);
	context.fast_block_idempotent_mru_store_elision_published = true;
#else
	(void)context;
#endif
}

template<FastBlockMruStoreSite Site>
inline void SetFastBlockMru(X64ThreadContext& context, size_t set_index,
	                        uint8_t way, bool idempotent_elision)
{
	static_assert(Site != FastBlockMruStoreSite::Count);
	auto& current = g_fast_block_mru[set_index];
#if LUMEN_X64_A64_FAST_BLOCK_IDEMPOTENT_MRU_STORE_ELISION_COMPILED
	// Reload the TLS byte at the assignment boundary. Translators and nested
	// Runs may reuse this set, so no earlier observation is safe to carry here.
	if (idempotent_elision && current == way)
	{
#if defined(LUMEN_CPU_X64_TEST)
		g_fast_block_test_mru_elisions[static_cast<size_t>(Site)]++;
#endif
		RecordFastBlockIdempotentMruStoreElision(context);
		return;
	}
#else
	(void)context;
	(void)idempotent_elision;
#endif
#if defined(LUMEN_CPU_X64_TEST)
	g_fast_block_test_mru_stores[static_cast<size_t>(Site)]++;
#endif
	current = way;
}

void InvalidateFastBlockDenseDirectoryIdentity(FastBlock* block)
{
#if LUMEN_X64_A64_FAST_BLOCK_DENSE_DIRECTORY_COMPILED
	if (!FastBlockDenseDirectoryRequested()) return;
	size_t set_index = 0;
	size_t way = 0;
	if (!FastBlockDenseDirectoryCoordinates(block, &set_index, &way)) return;
	g_fast_block_dense_directory[set_index][way] = 0;
#else
	(void)block;
#endif
}

void PublishFastBlockIdentity(FastBlock* block, uint64_t rip)
{
	if (block == nullptr) return;
	block->rip = rip;
#if LUMEN_X64_A64_FAST_BLOCK_DENSE_DIRECTORY_COMPILED
	if (!FastBlockDenseDirectoryRequested()) return;
	size_t set_index = 0;
	size_t way = 0;
	if (!FastBlockDenseDirectoryCoordinates(block, &set_index, &way)) return;
	// Publish the tag only after the canonical payload owns the identity.
	g_fast_block_dense_directory[set_index][way] = rip;
#endif
}

