#define LUMEN_X64_INLINE_FIXED_SIGNATURE_ALWAYS_INLINE __forceinline
#elif defined(__clang__) || defined(__GNUC__)
#define LUMEN_X64_INLINE_FIXED_SIGNATURE_ALWAYS_INLINE \
	inline __attribute__((always_inline))
