size_t A64DynarecCacheSetIndex(uint64_t rip)
{
	// Guest blocks within one module often differ only in their low bits.
	// Fold higher address bits before the power-of-two mask so those blocks do
	// not collapse into the same small native-code set.
	uint64_t key = rip >> 1u;
	key ^= key >> 11u;
	key ^= key >> 22u;
	return static_cast<size_t>(key) & (A64_DYNAREC_CACHE_SETS - 1);
}

bool A64DynarecCacheHealthy(const X64ThreadContext& context)
{
	return context.a64_dynarec_healthy &&
	       (context.a64_dynarec_cache == nullptr ||
	        context.a64_dynarec_cache->healthy);
}

