#if defined(LUMEN_A64_DYNAREC_RFLAGS_PROFILE)
void ConfigureA64DynarecRflagsProfileCache(A64DynarecCache& cache)
{
	// One plain owner-local branch is the complete steady-state cost. Global
	// synchronization and receipt election occur exactly once for each cache.
	if (cache.rflags_profile_configuration_checked) return;
	cache.rflags_profile_configuration_checked = true;

	auto& profile = g_a64_dynarec_rflags_profile;
#if LUMEN_X64_A64_COMPILED_ARCHIVE
	const bool archive_ready = cache.compiled_archive != nullptr;
#else
	const bool archive_ready = false;
#endif
	const size_t archive_entries = A64DynarecCompiledArchiveEntryLimit();
	const bool production_shape =
	    cache.Ready() && cache.healthy &&
	    cache.profile == A64DynarecCacheProfile::SeparateNegative &&
	    cache.delayed_positive_admission && cache.verified_ir_pipeline &&
	    cache.lazy_ir_storage && cache.compiled_archive_requested &&
	    archive_ready && archive_entries == 1024u &&
	    A64Dynarec::IsJitPageRecycleEnabled();
	std::lock_guard<std::mutex> lock(profile.mutex);
	RecordA64DynarecRflagsProfileCacheOwnerLocked(production_shape);
	if (profile.cache_configuration_reported) return;
	profile.cache_configuration_reported = true;
	std::fprintf(
	    stderr,
	    "[A64_DYNAREC_RFLAGS_PROFILE_CACHE] ready=%u healthy=%u"
	    " separate_negative=%u delayed_positive_admission=%u"
	    " verified_ir_pipeline=%u lazy_ir_storage=%u"
	    " archive_requested=%u archive_ready=%u archive_entries=%zu"
	    " jit_page_recycle=%u production_shape=%u schema=1\n",
	    cache.Ready() ? 1u : 0u, cache.healthy ? 1u : 0u,
	    cache.profile == A64DynarecCacheProfile::SeparateNegative ? 1u : 0u,
	    cache.delayed_positive_admission ? 1u : 0u,
	    cache.verified_ir_pipeline ? 1u : 0u,
	    cache.lazy_ir_storage ? 1u : 0u,
	    cache.compiled_archive_requested ? 1u : 0u,
	    archive_ready ? 1u : 0u,
	    archive_entries,
	    A64Dynarec::IsJitPageRecycleEnabled() ? 1u : 0u,
	    production_shape ? 1u : 0u);
	std::fflush(stderr);
}
#endif

