#if defined(LUMEN_A64_DYNAREC_PHASE6CM_PROFILE)
bool X64ExcludeA64DynarecPhase6CMSampleForHostCall()
{
	if (!A64Phase6CMProfileEffective()) return false;
	auto* sample = g_a64_phase6cm_current_block;
	if (sample == nullptr || sample->owner == nullptr ||
	    !sample->owner->window.active)
	{
		return false;
	}
	sample->owner->window.hle_excluded = true;
	return true;
}

void X64PollA64DynarecPhase6CMProfile(
	uint64_t present, bool checkpoint_reached)
{
	if (!A64Phase6CMProfileEffective()) return;
	const bool requested =
	    g_a64_phase6cm_snapshot_requested.exchange(
	        0, std::memory_order_acq_rel) != 0;
	if (checkpoint_reached || requested)
	{
		(void)ReportA64Phase6CMProfile(
		    checkpoint_reached && requested
		        ? "checkpoint_signal"
		        : checkpoint_reached ? "checkpoint" : "signal",
		    present, false);
	}
}

bool X64FinalizeA64DynarecPhase6CMProfile()
{
	auto& profile = g_a64_phase6cm_profile;
	std::call_once(profile.configure_once, []()
	{
		profile.configuration_ok.store(true, std::memory_order_release);
		profile.configuration_ready.store(true, std::memory_order_release);
		profile.effective.store(false, std::memory_order_release);
	});
	std::call_once(profile.finalize_once, []()
	{
		const bool was_effective =
		    profile.effective.load(std::memory_order_acquire);
		if (was_effective)
		{
			// The finalizer can drain its own lane exactly. Other guest owners are
			// represented by active_owners/windows_active and their explicit bounds;
			// waiting for them before desktop std::_Exit could deadlock on an HLE.
			FlushA64Phase6CMOwner(&g_a64_phase6cm_owner, true);
		}
		profile.effective.store(false, std::memory_order_release);
		g_a64_phase6cm_snapshot_requested.store(
		    0, std::memory_order_release);
		const bool configuration_ok =
		    profile.configuration_ok.load(std::memory_order_acquire);
		profile.finalize_result =
		    !was_effective
		        ? configuration_ok
		        : configuration_ok &&
		              ReportA64Phase6CMProfile("final", 0, true);
		profile.final_complete.store(true, std::memory_order_release);
	});
	return profile.finalize_result;
}
#endif

