bool X64FinalizeA64DynarecDenseAsyncCompilation()
{
#if LUMEN_X64_A64_DIRECT_BLOCK_BINDING
	if (!A64DynarecDenseAsyncCompilationRequested()) return true;
	const bool drained =
	    FastBlockA64DenseAsyncServiceGlobal().CloseAdmissionAndDrain();
	const auto* budget = FastBlockA64DenseAsyncBudgetGlobal();
	const size_t outstanding =
	    budget != nullptr
	        ? budget->outstanding.load(std::memory_order_acquire)
	        : A64_DENSE_ASYNC_GLOBAL_LIMIT;
	const uint64_t submitted =
	    budget != nullptr ? budget->submitted.load(std::memory_order_relaxed) : 0;
	const uint64_t started =
	    budget != nullptr ? budget->started.load(std::memory_order_relaxed) : 0;
	const uint64_t completed =
	    budget != nullptr ? budget->completed.load(std::memory_order_relaxed) : 0;
	const uint64_t cancelled_before_start =
	    budget != nullptr
	        ? budget->cancelled_before_start.load(std::memory_order_relaxed)
	        : 0;
	const uint64_t cancelled =
	    budget != nullptr ? budget->cancelled.load(std::memory_order_relaxed) : 0;
	const uint64_t compiled_ok =
	    budget != nullptr ? budget->compiled_ok.load(std::memory_order_relaxed)
	                      : 0;
	const uint64_t installed =
	    budget != nullptr ? budget->installed.load(std::memory_order_relaxed) : 0;
	const uint64_t fatal =
	    budget != nullptr ? budget->fatal.load(std::memory_order_relaxed) : 0;
	const bool clean = drained && submitted != 0 && compiled_ok != 0 &&
	                   fatal == 0 &&
	                   submitted == started + cancelled_before_start &&
	                   started == completed + cancelled;
	std::fprintf(
	    stderr,
	    "[A64_DENSE_ASYNC_FINAL] drained=%u queued=0 active=0 "
	    "outstanding=%zu submitted=%" PRIu64 " started=%" PRIu64
	    " compiled_ok=%" PRIu64 " completed=%" PRIu64
	    " ready_published=%" PRIu64 " ready_dropped=%" PRIu64
	    " installed=%" PRIu64 " stale=%" PRIu64
	    " probation_started=%" PRIu64 " probation_promoted=%" PRIu64
	    " probation_dropped=%" PRIu64
	    " cancelled_before_start=%" PRIu64 " cancelled=%" PRIu64
	    " fatal=%" PRIu64 " queue_full=%" PRIu64 " status=%s\n",
	    drained ? 1u : 0u, outstanding,
	    submitted, started,
	    compiled_ok,
	    completed,
	    budget != nullptr
	        ? budget->ready_published.load(std::memory_order_relaxed)
	        : 0,
	    budget != nullptr
	        ? budget->ready_dropped.load(std::memory_order_relaxed)
	        : 0,
	    installed,
	    budget != nullptr ? budget->stale.load(std::memory_order_relaxed) : 0,
	    budget != nullptr
	        ? budget->probation_started.load(std::memory_order_relaxed)
	        : 0,
	    budget != nullptr
	        ? budget->probation_promoted.load(std::memory_order_relaxed)
	        : 0,
	    budget != nullptr
	        ? budget->probation_dropped.load(std::memory_order_relaxed)
	        : 0,
	    cancelled_before_start,
	    cancelled,
	    fatal,
	    budget != nullptr
	        ? budget->queue_full.load(std::memory_order_relaxed)
	        : 0,
	    clean ? "clean" : "invalid");
	std::fflush(stderr);
	return clean;
#else
	return true;
#endif
}

