uint64_t X64Interpreter::LegacyAddressTranslate(void* context, uint64_t address, size_t size, bool write)
{
	const auto* interpreter = static_cast<const X64Interpreter*>(context);
	return interpreter != nullptr && interpreter->m_address_translate != nullptr
	           ? interpreter->m_address_translate(address, size, write)
	           : 0;
}

bool X64Interpreter::HasAddressTranslator() const
{
	return m_context_address_translate != nullptr || m_address_translate != nullptr;
}

uint64_t X64Interpreter::TranslateGuestAddress(uint64_t address, size_t size, bool write) const
{
	if (m_context_address_translate != nullptr)
	{
		return m_context_address_translate(m_address_translate_context, address, size, write);
	}
	return m_address_translate != nullptr ? m_address_translate(address, size, write) : address;
}

