bool X64ValidateRegionEngineV2ScalarParityForTest()
{
	using X64RegionV2::Frame;
	using X64RegionV2::OpResult;

	constexpr std::array<FastOpKind, 6> supported {{
	    FastOpKind::Nop,
	    FastOpKind::MovImmReg32,
	    FastOpKind::AddReg32Imm,
	    FastOpKind::CmpReg32Imm,
	    FastOpKind::Jcc,
	    FastOpKind::Jmp,
	}};
	size_t supported_count = 0;
	for (uint16_t ordinal = 0;
	     ordinal <= static_cast<uint8_t>(FastOpKind::TestNoFlags); ordinal++)
	{
		if (X64RegionV2::IsSupportedKind(
		        static_cast<FastOpKind>(ordinal)))
		{
			supported_count++;
		}
	}
	if (supported_count != supported.size()) return false;
	for (const auto kind: supported)
	{
		if (!X64RegionV2::IsSupportedKind(kind)) return false;
	}

	auto make_frame = [](const X64State& state)
	{
		Frame frame;
		frame.rax = state.gpr[0];
		frame.rcx = state.gpr[1];
		frame.rdx = state.gpr[2];
		frame.rbx = state.gpr[3];
		frame.rip = state.rip;
		frame.rflags = state.rflags;
		return frame;
	};
	auto states_equal = [](
		const Frame& frame, const X64State& state, const X64State& initial)
	{
		for (uint8_t reg = 0; reg < 4; reg++)
		{
			if (X64RegionV2::ReadRegister(frame, reg) != state.gpr[reg])
				return false;
		}
		for (uint8_t reg = 4; reg < 16; reg++)
		{
			if (state.gpr[reg] != initial.gpr[reg]) return false;
		}
		return frame.rip == state.rip && frame.rflags == state.rflags;
	};

	alignas(INSTRUCTION_PAGE_SIZE) static std::array<
	    uint8_t, INSTRUCTION_PAGE_SIZE> parity_code {};
	const uint64_t code_rip =
	    reinterpret_cast<uint64_t>(parity_code.data());
	auto matches_canonical = [&](const FastOp& operation,
	                             const X64State& initial)
	{
		X64State canonical = initial;
		X64ThreadContext context {};
		context.instruction_page_guest_begin = code_rip;
		context.instruction_page_host_begin = code_rip;
		context.instruction_page_size = INSTRUCTION_PAGE_SIZE;
		context.current_state = &canonical;
		FastBlock block {};
		block.valid = true;
		block.rip = code_rip;
		block.byte_count = 1;
		block.op_count = 1;
		block.bytes[0] = parity_code[0];
		block.ops[0] = operation;
		block.vmovd_reg32_to_xmm = FAST_BLOCK_EXECUTION_REENTRY_SAFE;

		Frame regional = make_frame(initial);
		const auto regional_result =
		    X64RegionV2::Execute(regional, operation);
		if (regional_result == OpResult::Unsupported) return false;
		if (regional_result == OpResult::Continue)
			regional.rip = operation.rip + operation.length;
		const uint8_t canonical_retired =
		    ExecuteFastBlock(context, &canonical, block, nullptr);
		return canonical_retired == 1 &&
		       states_equal(regional, canonical, initial);
	};

	constexpr std::array<uint32_t, 9> values {{
	    0,
	    1,
	    0x0f,
	    0x10,
	    0x7fffffff,
	    0x80000000,
	    0xfffffffe,
	    0xffffffff,
	    0x5aa55aa5,
	}};
	constexpr std::array<uint64_t, 3> flag_seeds {{
	    0,
	    UINT64_C(0xffffffffffffffff),
	    UINT64_C(0x202),
	}};
	auto initial_state = [&](uint8_t selected, uint32_t value,
	                         uint64_t flags)
	{
		X64State state {};
		for (uint8_t reg = 0; reg < 16; reg++)
		{
			state.gpr[reg] =
			    UINT64_C(0xa5a5000000000000) |
			    (static_cast<uint64_t>(reg) << 32u) |
			    (UINT32_C(0x1020304) * (reg + 1u));
		}
		state.gpr[selected] =
		    UINT64_C(0xdeadbeef00000000) | value;
		state.rip = code_rip;
		state.rflags = flags;
		return state;
	};

	FastOp operation {};
	operation.rip = code_rip;
	operation.length = 1;
	operation.target = code_rip + 0x40;
	operation.kind = FastOpKind::Nop;
	if (!matches_canonical(operation, initial_state(0, 0, 0x202)))
		return false;
	operation.kind = FastOpKind::Jmp;
	if (!matches_canonical(operation, initial_state(0, 0, 0x202)))
		return false;
	for (const auto kind: {
	         FastOpKind::MovImmReg32,
	         FastOpKind::AddReg32Imm,
	         FastOpKind::CmpReg32Imm,
	     })
	{
		operation.kind = kind;
		operation.dst = 4;
		Frame invalid = make_frame(initial_state(0, 0, 0x202));
		if (X64RegionV2::Execute(invalid, operation) != OpResult::Unsupported)
			return false;
	}

	for (uint8_t reg = 0; reg < 4; reg++)
	{
		for (const uint32_t lhs: values)
		{
			for (const uint32_t rhs: values)
			{
				for (const uint64_t flags: flag_seeds)
				{
					operation.dst = reg;
					operation.immediate = static_cast<int32_t>(rhs);
					operation.kind = FastOpKind::MovImmReg32;
					if (!matches_canonical(
					        operation, initial_state(reg, lhs, flags)))
						return false;
					operation.kind = FastOpKind::AddReg32Imm;
					if (!matches_canonical(
					        operation, initial_state(reg, lhs, flags)))
						return false;
					operation.kind = FastOpKind::CmpReg32Imm;
					if (!matches_canonical(
					        operation, initial_state(reg, lhs, flags)))
						return false;
				}
			}
		}
	}

	constexpr std::array<uint64_t, 5> condition_flags {{
	    FLAG_CF,
	    FLAG_PF,
	    FLAG_ZF,
	    FLAG_SF,
	    FLAG_OF,
	}};
	for (uint8_t combination = 0; combination < 32; combination++)
	{
		uint64_t flags = UINT64_C(0x202);
		for (uint8_t bit = 0; bit < condition_flags.size(); bit++)
		{
			if ((combination & (1u << bit)) != 0)
				flags |= condition_flags[bit];
		}
		for (uint8_t condition = 0; condition < 16; condition++)
		{
			operation.kind = FastOpKind::Jcc;
			operation.condition = condition;
			if (!matches_canonical(
			        operation, initial_state(0, 0, flags)))
				return false;
		}
	}
	return true;
}
#endif

