bool X64ValidateFastBlockTelemetrySnapshotFormatForTest()
{
	std::FILE* output = std::tmpfile();
	if (output == nullptr) return false;
	bool activation_signal = false;
	{
		std::lock_guard<std::mutex> lock(g_fast_block_telemetry.mutex);
		activation_signal = g_fast_block_telemetry.activation_signal;
		const uint64_t snapshots = g_fast_block_telemetry.snapshots;
		const uint64_t final_snapshots = g_fast_block_telemetry.final_snapshots;
		ReportFastBlockTelemetryLocked(false, output);
		g_fast_block_telemetry.snapshots = snapshots;
		g_fast_block_telemetry.final_snapshots = final_snapshots;
	}
	if (std::fseek(output, 0, SEEK_SET) != 0)
	{
		std::fclose(output);
		return false;
	}
	std::array<char, 256 * 1024> text {};
	const size_t length = std::fread(text.data(), 1, text.size() - 1, output);
	const bool complete = std::feof(output) != 0 && std::ferror(output) == 0;
	std::fclose(output);
	if (!complete || length == 0) return false;
	text[length] = '\0';

	constexpr const char* begin_prefix = "LUMEN_FAST_BLOCK_TELEMETRY_BEGIN ";
	constexpr const char* end_prefix = "LUMEN_FAST_BLOCK_TELEMETRY_END ";
	if (std::strncmp(text.data(), begin_prefix, std::strlen(begin_prefix)) != 0)
		return false;
	char* const begin_end = std::strchr(text.data(), '\n');
	if (begin_end == nullptr) return false;
	char* const payload = begin_end + 1;
	char* const end = std::strstr(payload, end_prefix);
	if (end == nullptr || (end != payload && end[-1] != '\n')) return false;
	char* const end_newline = std::strchr(end, '\n');
	if (end_newline == nullptr || end_newline + 1 != text.data() + length)
		return false;
	if (std::strstr(payload, begin_prefix) != nullptr ||
	    std::strstr(end + std::strlen(end_prefix), end_prefix) != nullptr)
	{
		return false;
	}

	auto parse_field = [](const char* line, const char* line_end,
	                      const char* field, uint64_t* value)
	{
		const char* found = std::strstr(line, field);
		if (found == nullptr || found >= line_end) return false;
		found += std::strlen(field);
		char* parsed_end = nullptr;
		const uint64_t parsed = std::strtoull(found, &parsed_end, 0);
		if (parsed_end == found || parsed_end > line_end) return false;
		*value = parsed;
		return true;
	};
	uint64_t begin_version = 0;
	uint64_t begin_snapshot = 0;
	uint64_t begin_attempts = 0;
	uint64_t begin_ordinary_blocks = 0;
	uint64_t begin_operation_labels = 0;
	uint64_t begin_pair_labels = 0;
	uint64_t begin_dropped = 0;
	uint64_t begin_dropped_unclassified = 0;
	uint64_t begin_dropped_sidecar = 0;
	uint64_t begin_dropped_reject_capacity = 0;
	uint64_t begin_dropped_thread_registry = 0;
	uint64_t begin_dropped_internal = 0;
	uint64_t begin_thread_count = 0;
	uint64_t begin_threads_dropped = 0;
	uint64_t begin_rows = 0;
	uint64_t begin_checksum = 0;
	uint64_t begin_final = 0;
	uint64_t begin_armed = 0;
	uint64_t end_snapshot = 0;
	uint64_t end_attempts = 0;
	uint64_t end_dropped = 0;
	uint64_t end_dropped_unclassified = 0;
	uint64_t end_dropped_sidecar = 0;
	uint64_t end_dropped_reject_capacity = 0;
	uint64_t end_dropped_thread_registry = 0;
	uint64_t end_dropped_internal = 0;
	uint64_t end_thread_count = 0;
	uint64_t end_threads_dropped = 0;
	uint64_t end_rows = 0;
	uint64_t end_checksum = 0;
	uint64_t end_valid = 0;
	uint64_t end_final = 0;
	uint64_t end_armed = 0;
	const char* const activation_fields =
	    activation_signal
	        ? " activation=signal armed=1 signal=SIGUSR1"
	        : " activation=immediate armed=1 signal=none";
	const char* const begin_activation =
	    std::strstr(text.data(), activation_fields);
	const char* const end_activation = std::strstr(end, activation_fields);
	if (!parse_field(text.data(), begin_end, " version=", &begin_version) ||
	    begin_version != 6 ||
	    !parse_field(text.data(), begin_end, " snapshot=", &begin_snapshot) ||
	    !parse_field(text.data(), begin_end, " attempts=", &begin_attempts) ||
	    !parse_field(text.data(), begin_end, " ordinary_blocks=",
	                 &begin_ordinary_blocks) ||
	    !parse_field(text.data(), begin_end, " operation_labels=",
	                 &begin_operation_labels) ||
	    !parse_field(text.data(), begin_end, " pair_labels=",
	                 &begin_pair_labels) ||
	    !parse_field(text.data(), begin_end, " dropped=", &begin_dropped) ||
	    !parse_field(text.data(), begin_end, " dropped_unclassified=",
	                 &begin_dropped_unclassified) ||
	    !parse_field(text.data(), begin_end, " dropped_sidecar=",
	                 &begin_dropped_sidecar) ||
	    !parse_field(text.data(), begin_end, " dropped_reject_capacity=",
	                 &begin_dropped_reject_capacity) ||
	    !parse_field(text.data(), begin_end, " dropped_thread_registry=",
	                 &begin_dropped_thread_registry) ||
	    !parse_field(text.data(), begin_end, " dropped_internal=",
	                 &begin_dropped_internal) ||
	    !parse_field(text.data(), begin_end, " thread_count=",
	                 &begin_thread_count) ||
	    !parse_field(text.data(), begin_end, " threads_dropped=",
	                 &begin_threads_dropped) ||
	    !parse_field(text.data(), begin_end, " armed=", &begin_armed) ||
	    !parse_field(text.data(), begin_end, " rows=", &begin_rows) ||
		    !parse_field(text.data(), begin_end, " checksum=", &begin_checksum) ||
		    !parse_field(text.data(), begin_end, " final=", &begin_final) ||
	    begin_activation == nullptr || begin_activation >= begin_end ||
	    std::strstr(text.data(), " platform=") == nullptr ||
	    std::strstr(text.data(), " host_a64=") == nullptr ||
	    std::strstr(text.data(), " a64_env_requested=0") == nullptr ||
	    std::strstr(text.data(), " jit=0 a64=0") == nullptr ||
	    std::strstr(text.data(), " thread=") != nullptr ||
	    !parse_field(end, end_newline, " snapshot=", &end_snapshot) ||
	    !parse_field(end, end_newline, " attempts=", &end_attempts) ||
	    !parse_field(end, end_newline, " dropped=", &end_dropped) ||
	    !parse_field(end, end_newline, " dropped_unclassified=",
	                 &end_dropped_unclassified) ||
	    !parse_field(end, end_newline, " dropped_sidecar=",
	                 &end_dropped_sidecar) ||
	    !parse_field(end, end_newline, " dropped_reject_capacity=",
	                 &end_dropped_reject_capacity) ||
	    !parse_field(end, end_newline, " dropped_thread_registry=",
	                 &end_dropped_thread_registry) ||
	    !parse_field(end, end_newline, " dropped_internal=",
	                 &end_dropped_internal) ||
		    !parse_field(end, end_newline, " thread_count=",
		                 &end_thread_count) ||
	    !parse_field(end, end_newline, " threads_dropped=",
	                 &end_threads_dropped) ||
	    !parse_field(end, end_newline, " armed=", &end_armed) ||
	    !parse_field(end, end_newline, " valid=", &end_valid) ||
		    !parse_field(end, end_newline, " rows=", &end_rows) ||
		    !parse_field(end, end_newline, " checksum=", &end_checksum) ||
	    !parse_field(end, end_newline, " final=", &end_final) ||
	    end_activation == nullptr || end_activation >= end_newline)
	{
		return false;
	}

	size_t row_count = 0;
	size_t pair_row_count = 0;
	uint64_t reported_pair_count = 0;
	uint64_t previous_pair_count = UINT64_MAX;
	uint64_t previous_pair_key = 0;
	for (char* line = payload; line < end;)
	{
		char* const newline = std::strchr(line, '\n');
		if (newline == nullptr || newline >= end) return false;
		const bool pair_row =
		    std::strncmp(line, "LUMEN_FAST_BLOCK_TELEMETRY_PAIR ", 32) == 0;
		if (std::strncmp(line, "LUMEN_FAST_BLOCK_TELEMETRY_KIND ", 32) != 0 &&
		    !pair_row &&
		    std::strncmp(line, "LUMEN_FAST_BLOCK_TELEMETRY_RECOGNIZER ", 38) != 0 &&
		    std::strncmp(line, "LUMEN_FAST_BLOCK_TELEMETRY_REJECT ", 34) != 0)
		{
			return false;
		}
		if (pair_row)
		{
			uint64_t snapshot = 0;
			uint64_t rank = 0;
			uint64_t first = 0;
			uint64_t second = 0;
			uint64_t count = 0;
			if (!parse_field(line, newline, " snapshot=", &snapshot) ||
			    !parse_field(line, newline, " rank=", &rank) ||
			    !parse_field(line, newline, " first=", &first) ||
			    !parse_field(line, newline, " second=", &second) ||
			    !parse_field(line, newline, " count=", &count) ||
			    snapshot != begin_snapshot || rank != pair_row_count + 1u ||
			    first >= FAST_BLOCK_TELEMETRY_KIND_COUNT ||
			    second >= FAST_BLOCK_TELEMETRY_KIND_COUNT || count == 0)
			{
				return false;
			}
			const uint64_t key = (first << 8u) | second;
			if ((pair_row_count != 0 &&
			     (count > previous_pair_count ||
			      (count == previous_pair_count && key <= previous_pair_key))) ||
			    reported_pair_count > UINT64_MAX - count)
			{
				return false;
			}
			previous_pair_count = count;
			previous_pair_key = key;
			reported_pair_count += count;
			pair_row_count++;
		}
		row_count++;
		line = newline + 1;
	}
	uint64_t computed_checksum = FastBlockTelemetryChecksum(
	    FAST_BLOCK_TELEMETRY_CHECKSUM_OFFSET, payload,
	    static_cast<size_t>(end - payload));
	if (computed_checksum == 0) computed_checksum = 1;
	return begin_snapshot == end_snapshot && begin_attempts == end_attempts &&
	       begin_operation_labels >= begin_ordinary_blocks &&
	       begin_pair_labels ==
	           begin_operation_labels - begin_ordinary_blocks &&
	       pair_row_count <= FAST_BLOCK_TELEMETRY_PAIR_REPORT_COUNT &&
	       reported_pair_count <= begin_pair_labels &&
	       (pair_row_count == FAST_BLOCK_TELEMETRY_PAIR_REPORT_COUNT ||
	        reported_pair_count == begin_pair_labels) &&
	       begin_dropped == end_dropped && begin_rows == end_rows &&
	       begin_dropped_unclassified == end_dropped_unclassified &&
	       begin_dropped_sidecar == end_dropped_sidecar &&
	       begin_dropped_reject_capacity == end_dropped_reject_capacity &&
	       begin_dropped_thread_registry == end_dropped_thread_registry &&
		       begin_dropped_internal == end_dropped_internal &&
		       begin_thread_count == end_thread_count &&
		       begin_threads_dropped == end_threads_dropped &&
		       end_valid ==
		           (begin_dropped == 0 && begin_threads_dropped == 0 ? 1u : 0u) &&
	       begin_armed == 1 && begin_armed == end_armed &&
	       begin_final == end_final &&
		       begin_rows == row_count && begin_checksum != 0 &&
	       begin_checksum == end_checksum && begin_checksum == computed_checksum;
}
#endif

