bool X64ValidateA64DynarecGprCacheProfileStickySaturationForTest()
{
	auto& profile = g_a64_dynarec_gpr_cache_profile;
	std::lock_guard<std::mutex> lock(profile.mutex);
	auto& counter = profile.candidate_prepare_words;
	const uint64_t saved_counter =
	    counter.load(std::memory_order_relaxed);
	const bool saved_overflow = profile.overflow.load(std::memory_order_relaxed);
	counter.store(UINT64_MAX - 1u, std::memory_order_relaxed);
	profile.overflow.store(false, std::memory_order_relaxed);
	const uint64_t saturated =
	    AddA64DynarecGprCacheProfileBounded(&counter, 2u);
	const bool first_overflow =
	    saturated == UINT64_MAX &&
	    profile.overflow.load(std::memory_order_relaxed);
	AddA64DynarecGprCacheProfileBounded(&counter, 0u);
	const bool sticky =
	    counter.load(std::memory_order_relaxed) == UINT64_MAX &&
	    profile.overflow.load(std::memory_order_relaxed);
	counter.store(saved_counter, std::memory_order_relaxed);
	profile.overflow.store(saved_overflow, std::memory_order_relaxed);
	return first_overflow && sticky;
}
#endif

