bool X64CaptureA64DynarecPhase6CKProfileReuseForTest(
	X64A64DynarecPhase6CKProfileReuseSnapshot* snapshot)
{
#if defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE)
	if (snapshot == nullptr ||
	    !g_a64_dense_phase6ck_profile.effective.load(
	        std::memory_order_acquire))
	{
		return false;
	}
	A64DensePhase6CKCountersSnapshot counters {};
	if (!CaptureA64DensePhase6CKCounters(&counters)) return false;
	uint64_t reuse_second = 0;
	uint64_t reuse_third = 0;
	for (size_t bucket = 0; bucket < A64_DENSE_PHASE6CK_REUSE_BUCKETS;
	     bucket++)
	{
		reuse_second += counters.reuse_distance[0][bucket];
		reuse_third += counters.reuse_distance[1][bucket];
	}
	*snapshot = {
	    counters.identity_first,
	    counters.identity_second,
	    counters.identity_third,
	    reuse_second,
	    reuse_third,
	    counters.retired_once,
	    counters.retired_twice,
	    counters.retired_three_plus,
	    counters.live_once,
	    counters.live_twice,
	    counters.live_three_plus,
	};
	return true;
#else
	(void)snapshot;
	return false;
#endif
}

bool X64CaptureA64DynarecPhase6CKProfileFallbackForTest(
	X64A64DynarecPhase6CKProfileFallbackSnapshot* snapshot)
{
#if defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE)
	if (snapshot == nullptr ||
	    !g_a64_dense_phase6ck_profile.effective.load(
	        std::memory_order_acquire))
	{
		return false;
	}
	A64DensePhase6CKCountersSnapshot counters {};
	if (!CaptureA64DensePhase6CKCounters(&counters)) return false;
	constexpr uint64_t unflushed_per_owner =
	    (A64_DENSE_PHASE6CK_FALLBACK_BATCH_SIZE - 1u) * 2u;
	const uint64_t unflushed_blocks_bound =
	    counters.fallback_active_owners <= UINT64_MAX / unflushed_per_owner
	        ? counters.fallback_active_owners * unflushed_per_owner
	        : UINT64_MAX;
	*snapshot = {
	    A64_DENSE_PHASE6CK_FALLBACK_SAMPLE_INTERVAL,
	    A64_DENSE_PHASE6CK_FALLBACK_BATCH_SIZE,
	    counters.fallback_active_owners,
	    unflushed_blocks_bound,
	    counters.fallback_ordinary_blocks,
	    counters.fallback_ordinary_steps,
	    counters.fallback_ordinary_samples,
	    counters.fallback_ordinary_sample_steps,
	    counters.fallback_ordinary_sample_ns,
	    counters.fallback_ordinary_flushes,
	    counters.fallback_precise_blocks,
	    counters.fallback_precise_steps,
	    counters.fallback_precise_samples,
	    counters.fallback_precise_sample_steps,
	    counters.fallback_precise_sample_ns,
	    counters.fallback_precise_flushes,
	};
	return true;
#else
	(void)snapshot;
	return false;
#endif
}

bool X64RecordA64DynarecPhase6CKFallbackForTest(
	bool precise, uint64_t steps, uint64_t sampled_ns)
{
#if defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE)
	if (!g_a64_dense_phase6ck_profile.effective.load(
	        std::memory_order_acquire))
	{
		return false;
	}
	auto& owner = g_a64_dense_phase6ck_fallback_tls;
	if (!RegisterA64DensePhase6CKFallbackOwner(&owner)) return false;
	const auto kind = precise ? A64DensePhase6CKFallbackKind::Precise
	                          : A64DensePhase6CKFallbackKind::Ordinary;
	auto& pending = precise ? owner.precise : owner.ordinary;
	pending.ordinal++;
	const bool sampled =
	    pending.ordinal % A64_DENSE_PHASE6CK_FALLBACK_SAMPLE_INTERVAL == 0;
	RecordA64DensePhase6CKFallbackCompletion(
	    kind, steps, sampled, sampled ? sampled_ns : 0);
	return true;
#else
	(void)precise;
	(void)steps;
	(void)sampled_ns;
	return false;
#endif
}

