bool X64StressA64DynarecPhase6CKSnapshotConsistencyForTest()
{
#if defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE)
	auto& profile = g_a64_dense_phase6ck_profile;
	if (!profile.effective.load(std::memory_order_acquire)) return false;
	{
		A64DensePhase6CKUpdateScope update(true);
		if (!update) return false;
		profile.snapshot_stress_first.store(0, std::memory_order_relaxed);
		profile.snapshot_stress_second.store(0, std::memory_order_relaxed);
	}

	constexpr size_t writer_count = 3;
	constexpr size_t iterations = 4096;
	std::atomic<bool> start {false};
	std::atomic<bool> first_capture_observed {false};
	std::atomic<bool> mismatch {false};
	std::atomic<size_t> active {writer_count};
	std::atomic<uint64_t> next_value {0};
	std::atomic<uint64_t> captures {0};
	std::array<std::thread, writer_count> writers;
	for (size_t writer = 0; writer < writer_count; writer++)
	{
		writers[writer] = std::thread([&, writer]()
		{
			while (!start.load(std::memory_order_acquire))
				std::this_thread::yield();
			for (size_t iteration = 0; iteration < iterations; iteration++)
			{
				const uint64_t value =
				    next_value.fetch_add(1, std::memory_order_relaxed) + 1u;
				{
					A64DensePhase6CKUpdateScope update(true);
					if (!update)
					{
						mismatch.store(true, std::memory_order_relaxed);
						break;
					}
					profile.snapshot_stress_first.store(
					    value, std::memory_order_relaxed);
					if (((iteration + writer) & 7u) == 0)
						std::this_thread::yield();
					profile.snapshot_stress_second.store(
					    value, std::memory_order_relaxed);
				}
				if (iteration == 0)
				{
					while (!first_capture_observed.load(
					           std::memory_order_acquire))
					{
						std::this_thread::yield();
					}
				} else if ((iteration & 3u) == 0)
				{
					std::this_thread::yield();
				}
			}
			active.fetch_sub(1, std::memory_order_release);
		});
	}
	start.store(true, std::memory_order_release);
	while (active.load(std::memory_order_acquire) != 0)
	{
		A64DensePhase6CKCountersSnapshot captured {};
		if (!CaptureA64DensePhase6CKCounters(&captured))
		{
			std::this_thread::yield();
			continue;
		}
		captures.fetch_add(1, std::memory_order_relaxed);
		first_capture_observed.store(true, std::memory_order_release);
		if (captured.snapshot_stress_first !=
		    captured.snapshot_stress_second)
		{
			mismatch.store(true, std::memory_order_relaxed);
		}
	}
	for (auto& writer: writers) writer.join();
	A64DensePhase6CKCountersSnapshot final {};
	return CaptureA64DensePhase6CKCounters(&final) &&
	       captures.load(std::memory_order_relaxed) != 0 &&
	       !mismatch.load(std::memory_order_relaxed) &&
	       final.snapshot_stress_first == final.snapshot_stress_second &&
	       (profile.snapshot_generation.load(std::memory_order_acquire) & 1u) ==
	           0;
#else
	return false;
#endif
}

bool X64StressA64DynarecPhase6CKFinalizationForTest()
{
#if defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE)
	auto& profile = g_a64_dense_phase6ck_profile;
	if (!profile.effective.load(std::memory_order_acquire)) return false;

	// The test coordinator may own a shard from the sampling checks. Drain it so
	// the one deliberately live worker below is the only endpoint uncertainty.
	FlushA64DensePhase6CKFallbackTls(
	    &g_a64_dense_phase6ck_fallback_tls, true);
	std::atomic<bool> worker_ready {false};
	std::atomic<bool> release_worker {false};
	std::atomic<bool> worker_run_active {false};
	std::atomic<bool> worker_records_ok {true};
	std::atomic<bool> late_record_rejected {false};
	std::thread worker([&]()
	{
		A64DensePhase6CKRunScope run_scope;
		worker_run_active.store(run_scope.Active(), std::memory_order_release);
		for (uint64_t event = 0; event < 17; event++)
		{
			if (!X64RecordA64DynarecPhase6CKFallbackForTest(
			        false, 1, 0))
			{
				worker_records_ok.store(false, std::memory_order_relaxed);
				break;
			}
		}
		worker_ready.store(true, std::memory_order_release);
		while (!release_worker.load(std::memory_order_acquire))
			std::this_thread::yield();
		late_record_rejected.store(
		    !X64RecordA64DynarecPhase6CKFallbackForTest(false, 1, 0),
		    std::memory_order_release);
	});
	while (!worker_ready.load(std::memory_order_acquire))
		std::this_thread::yield();
	if (!worker_run_active.load(std::memory_order_acquire) ||
	    !worker_records_ok.load(std::memory_order_acquire))
	{
		release_worker.store(true, std::memory_order_release);
		worker.join();
		return false;
	}

	std::atomic<bool> writer_ready {false};
	std::atomic<bool> release_writer {false};
	std::atomic<bool> writer_admitted {false};
	std::thread blocking_writer([&]()
	{
		A64DensePhase6CKUpdateScope update(true);
		writer_admitted.store(static_cast<bool>(update),
		                      std::memory_order_release);
		if (update)
		{
			constexpr uint64_t sentinel = UINT64_C(0x6c6b1415);
			profile.snapshot_stress_first.store(
			    sentinel, std::memory_order_relaxed);
			writer_ready.store(true, std::memory_order_release);
			while (!release_writer.load(std::memory_order_acquire))
				std::this_thread::yield();
			profile.snapshot_stress_second.store(
			    sentinel, std::memory_order_relaxed);
		} else
		{
			writer_ready.store(true, std::memory_order_release);
		}
	});
	while (!writer_ready.load(std::memory_order_acquire))
		std::this_thread::yield();
	if (!writer_admitted.load(std::memory_order_acquire))
	{
		blocking_writer.join();
		release_worker.store(true, std::memory_order_release);
		worker.join();
		return false;
	}

	bool final_result = false;
	std::thread finalizer([&]()
	{
		final_result = X64FinalizeA64DynarecPhase6CKProfile();
	});
	while (!profile.finalizing.load(std::memory_order_acquire))
		std::this_thread::yield();
	const bool waited_for_writer =
	    !profile.final_complete.load(std::memory_order_acquire);
	release_writer.store(true, std::memory_order_release);
	blocking_writer.join();
	// FINAL must now complete while the admitted Run is deliberately held open.
	// This simultaneously proves the brief writer drain and rejects a full-Run
	// drain that would deadlock the desktop frame-limit shutdown path.
	while (!profile.final_complete.load(std::memory_order_acquire))
		std::this_thread::yield();
	finalizer.join();
	A64DensePhase6CKCountersSnapshot terminal {};
	const uint64_t terminal_generation =
	    profile.snapshot_generation.load(std::memory_order_acquire);
	const bool terminal_captured =
	    CaptureA64DensePhase6CKCounters(&terminal);

	release_worker.store(true, std::memory_order_release);
	worker.join();
	A64DensePhase6CKCountersSnapshot after_late {};
	const bool after_late_captured =
	    CaptureA64DensePhase6CKCounters(&after_late);
	A64DensePhase6CKUpdateScope rejected_update(true);
	const bool admission_rejected = !rejected_update;
	const uint64_t after_generation =
	    profile.snapshot_generation.load(std::memory_order_acquire);

	auto snapshots_equal = [](const A64DensePhase6CKCountersSnapshot& lhs,
	                          const A64DensePhase6CKCountersSnapshot& rhs)
	{
		return lhs.lower_attempts == rhs.lower_attempts &&
		       lhs.lower_ok == rhs.lower_ok && lhs.lower_fail == rhs.lower_fail &&
		       lhs.lower_ns == rhs.lower_ns &&
		       lhs.compile_attempts == rhs.compile_attempts &&
		       lhs.compile_ok == rhs.compile_ok &&
		       lhs.compile_capacity == rhs.compile_capacity &&
		       lhs.compile_fail == rhs.compile_fail &&
		       lhs.compile_ns == rhs.compile_ns &&
		       lhs.staging_ns == rhs.staging_ns &&
		       lhs.emit_ns == rhs.emit_ns &&
		       lhs.allocate_ns == rhs.allocate_ns &&
		       lhs.publish_ns == rhs.publish_ns &&
		       lhs.code_bytes == rhs.code_bytes &&
		       lhs.code_capacity == rhs.code_capacity &&
		       lhs.identity_first == rhs.identity_first &&
		       lhs.identity_second == rhs.identity_second &&
		       lhs.identity_third == rhs.identity_third &&
		       lhs.reuse_distance == rhs.reuse_distance &&
		       lhs.reset_reason == rhs.reset_reason &&
		       lhs.reset_busy == rhs.reset_busy &&
		       lhs.retired_once == rhs.retired_once &&
		       lhs.retired_twice == rhs.retired_twice &&
		       lhs.retired_three_plus == rhs.retired_three_plus &&
		       lhs.live_once == rhs.live_once &&
		       lhs.live_twice == rhs.live_twice &&
		       lhs.live_three_plus == rhs.live_three_plus &&
		       lhs.bypasses == rhs.bypasses &&
		       lhs.capacity_fallbacks == rhs.capacity_fallbacks &&
		       lhs.fallback_active_owners == rhs.fallback_active_owners &&
		       lhs.fallback_ordinary_blocks == rhs.fallback_ordinary_blocks &&
		       lhs.fallback_ordinary_steps == rhs.fallback_ordinary_steps &&
		       lhs.fallback_ordinary_samples == rhs.fallback_ordinary_samples &&
		       lhs.fallback_ordinary_sample_steps ==
		           rhs.fallback_ordinary_sample_steps &&
		       lhs.fallback_ordinary_sample_ns ==
		           rhs.fallback_ordinary_sample_ns &&
		       lhs.fallback_ordinary_flushes ==
		           rhs.fallback_ordinary_flushes &&
		       lhs.fallback_precise_blocks == rhs.fallback_precise_blocks &&
		       lhs.fallback_precise_steps == rhs.fallback_precise_steps &&
		       lhs.fallback_precise_samples == rhs.fallback_precise_samples &&
		       lhs.fallback_precise_sample_steps ==
		           rhs.fallback_precise_sample_steps &&
		       lhs.fallback_precise_sample_ns == rhs.fallback_precise_sample_ns &&
		       lhs.fallback_precise_flushes == rhs.fallback_precise_flushes &&
		       lhs.snapshot_stress_first == rhs.snapshot_stress_first &&
		       lhs.snapshot_stress_second == rhs.snapshot_stress_second;
	};
	return final_result && waited_for_writer && terminal_captured &&
	       after_late_captured &&
	       terminal.fallback_active_owners == 1u &&
	       late_record_rejected.load(std::memory_order_acquire) &&
	       admission_rejected && snapshots_equal(terminal, after_late) &&
	       terminal_generation == after_generation &&
	       (after_generation & 1u) == 0;
#else
	return false;
#endif
}
#endif

