bool X64ValidateA64DynarecNativeOnlyAdmissionDefaultFinalizerForTest()
{
#if defined(LUMEN_CPU_X64_TEST) && defined(__APPLE__) && \
    defined(__aarch64__) && TARGET_OS_OSX && \
    !TARGET_OS_IPHONE && \
    !defined(LUMEN_A64_DYNAREC_PHASE6CK_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_PHASE6CM_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_PHASE6CO_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_RFLAGS_PROFILE) && \
    !defined(LUMEN_A64_DYNAREC_GPR_CACHE_PROFILE)
	if (std::getenv("LUMEN_X64_A64_DYNAREC_NATIVE_ONLY_ADMISSION") !=
	        nullptr ||
	    !A64Dynarec::IsHostSupported())
	{
		return false;
	}
	g_a64_dynarec_test_native_only_admission_default_override = 1;
	const bool requested = A64DynarecNativeOnlyAdmissionRequested();
	const bool strict =
	    A64DynarecNativeOnlyAdmissionStrictCoverageRequested();
	auto& telemetry = g_a64_dynarec_native_only_admission_telemetry;
	const bool coverage_zero_before =
	    !telemetry.effective.load(std::memory_order_acquire) &&
	    !telemetry.ordinary_routed.load(std::memory_order_acquire) &&
	    !telemetry.native_probe_bypassed.load(std::memory_order_acquire) &&
	    !telemetry.native_only_executed.load(std::memory_order_acquire);
	const uint64_t emissions_before =
	    g_a64_dynarec_test_native_only_admission_final_marker_emissions.load(
	        std::memory_order_acquire);
	const bool finalized = X64FinalizeA64DynarecNativeOnlyAdmission();
	const uint64_t emissions_after =
	    g_a64_dynarec_test_native_only_admission_final_marker_emissions.load(
	        std::memory_order_acquire);
	const bool coverage_zero_after =
	    !telemetry.effective.load(std::memory_order_acquire) &&
	    !telemetry.ordinary_routed.load(std::memory_order_acquire) &&
	    !telemetry.native_probe_bypassed.load(std::memory_order_acquire) &&
	    !telemetry.native_only_executed.load(std::memory_order_acquire);
	return requested && !strict && coverage_zero_before && finalized &&
	       emissions_before == 0 && emissions_after == 0 &&
	       coverage_zero_after;
#else
	return true;
#endif
}

