bool X64CorruptFastBlockDenseDirectoryForTest(uint64_t rip)
{
#if LUMEN_X64_A64_FAST_BLOCK_DENSE_DIRECTORY_COMPILED
	if (!FastBlockDenseDirectoryRequested() || rip == 0) return false;
	const size_t set_index = FastBlockCacheSet(rip);
	for (size_t way = 0; way < FAST_BLOCK_CACHE_WAYS; way++)
	{
		if (g_fast_blocks[set_index][way].rip != rip) continue;
		auto& tag = g_fast_block_dense_directory[set_index][way];
		if (tag != rip) return false;
		tag = rip == UINT64_MAX ? 1 : rip + 1;
		return true;
	}
	return false;
#else
	(void)rip;
	return false;
#endif
}

bool X64SwapFastBlockDenseDirectoryTagsForTest(uint64_t rip)
{
#if LUMEN_X64_A64_FAST_BLOCK_DENSE_DIRECTORY_COMPILED
	if (!FastBlockDenseDirectoryRequested() || rip == 0) return false;
	const size_t set_index = FastBlockCacheSet(rip);
	auto& set = g_fast_blocks[set_index];
	auto& tags = g_fast_block_dense_directory[set_index];
	size_t target_way = FAST_BLOCK_CACHE_WAYS;
	for (size_t way = 0; way < FAST_BLOCK_CACHE_WAYS; way++)
	{
		if (tags[way] != set[way].rip) return false;
		if (set[way].rip == rip) target_way = way;
	}
	if (target_way == FAST_BLOCK_CACHE_WAYS) return false;
	const size_t other_way = target_way ^ 1u;
	if (set[other_way].rip == 0 || set[other_way].rip == rip) return false;
	// Put the requested tag on the wrong payload. The next lookup must reject
	// that false positive, rebuild both tags and reuse the historical payload.
	std::swap(tags[target_way], tags[other_way]);
	return true;
#else
	(void)rip;
	return false;
#endif
}

size_t X64FastBlockDeadRflagsElisionCountForTest(uint64_t rip)
{
	const size_t set_index = FastBlockCacheSet(rip);
	for (const auto& block: g_fast_blocks[set_index])
	{
		if (block.rip != rip) continue;
		size_t count = 0;
		for (uint8_t index = 0; index < block.op_count; index++)
		{
			if (X64Fast::IsDeadRflagsElidedFastOpKind(
			        block.ops[index].kind))
			{
				count++;
			}
		}
		return count;
	}
	return 0;
}

bool X64A64DynarecFastBlockOperationSnapshotElisionEligibleForTest(
	uint64_t rip)
{
	const size_t set_index = FastBlockCacheSet(rip);
	for (const auto& block: g_fast_blocks[set_index])
	{
		if (block.rip == rip)
			return FastBlockOperationSnapshotElisionEligible(block);
	}
	return false;
}

