void X64ResetA64DynarecCacheForTest()
{
	if (g_a64_dynarec_cache != nullptr && !g_a64_dynarec_cache->IsQuiescent())
	{
		LatchA64DynarecUnhealthy(
		    g_thread_context, g_a64_dynarec_cache.get(),
		    A64DynarecUnhealthyReason::TestResetBusy);
		return;
	}
	g_a64_dynarec_cache.reset();
	g_thread_context.a64_dynarec_cache = nullptr;
	ClearAllFastBlockA64DirectBindings();
	ClearFastBlockA64PositiveAdmission();
	g_thread_context.a64_dynarec_healthy = true;
	g_a64_dynarec_test_poison_rip = 0;
	g_a64_dynarec_test_zero_accounting_rip = 0;
	g_a64_dynarec_test_partial_completed_rip = 0;
	g_a64_dynarec_test_bad_resume_rip = 0;
	g_a64_dynarec_test_busy_rip = 0;
	g_a64_dynarec_test_stable_negative_live_mismatch_rip = 0;
	g_a64_dynarec_test_archive_mutation_rip = 0;
	g_a64_dynarec_test_compile_failure_rip = 0;
	A64Dynarec::ResetIrVerificationTestCounters();
}

X64A64DynarecCacheTestStats X64GetA64DynarecCacheTestStats()
{
	X64A64DynarecCacheTestStats result {};
	if (g_a64_dynarec_cache != nullptr)
	{
		result         = g_a64_dynarec_cache->stats;
		result.separate_negative_cache =
		    g_a64_dynarec_cache->profile == A64DynarecCacheProfile::SeparateNegative;
		result.delayed_positive_admission =
		    g_a64_dynarec_cache->delayed_positive_admission;
#if LUMEN_X64_A64_COMPILED_ARCHIVE
		if (g_a64_dynarec_cache->compiled_archive != nullptr)
		{
			g_a64_dynarec_cache->compiled_archive->SnapshotGlobalForTest(&result);
		}
#endif
	}
#if LUMEN_X64_A64_COMPILED_ARCHIVE
	if (auto* global = A64DynarecCompiledArchiveGlobal(); global != nullptr)
	{
		std::lock_guard<std::mutex> lock(global->mutex);
		result.archive_global_capacity = global->resident_capacity;
		result.archive_global_peak = global->peak_capacity;
		result.archive_global_invalid = global->invalid;
	}

#endif
#if LUMEN_X64_A64_DIRECT_BLOCK_BINDING
	if (const auto* budget = FastBlockA64DenseAsyncBudgetGlobal();
	    budget != nullptr)
	{
		result.dense_async_probation_started =
		    budget->probation_started.load(std::memory_order_relaxed);
		result.dense_async_probation_promoted =
		    budget->probation_promoted.load(std::memory_order_relaxed);
		result.dense_async_probation_dropped =
		    budget->probation_dropped.load(std::memory_order_relaxed);
	}
#endif
	const auto ir_verification =
	    A64Dynarec::GetIrVerificationTestCounters();
	result.ir_instruction_validations =
	    ir_verification.instruction_validations;
	result.ir_full_block_verifications =
	    ir_verification.full_block_verifications;
	result.ir_structural_block_verifications =
	    ir_verification.structural_block_verifications;
	result.operation_snapshot_copies =
	    g_a64_dynarec_test_operation_snapshot_copies;
	result.operation_snapshot_elisions =
	    g_a64_dynarec_test_operation_snapshot_elisions;
	result.execution_signature_snapshots =
	    g_a64_dynarec_test_execution_signature_snapshots;
	result.ordinary_native_probe_attempts =
	    g_a64_dynarec_test_ordinary_native_probe_attempts;
	result.dead_rflags_elision_blocks =
	    g_fast_block_test_dead_rflags_elision_blocks;
	result.dead_rflags_elision_operations =
	    g_fast_block_test_dead_rflags_elision_operations;
	result.healthy = A64DynarecCacheHealthy();
	return result;
}

size_t X64A64DynarecCacheSetForTest(uint64_t rip)
{
	return A64DynarecCacheSetIndex(rip);
}

const void* X64A64DynarecPositiveOwnerForTest(uint64_t rip)
{
	if (g_a64_dynarec_cache == nullptr) return nullptr;
	const auto& set =
	    g_a64_dynarec_cache->sets[A64DynarecCacheSetIndex(rip)];
	for (const auto& entry: set.ways)
	{
		if (entry.state == A64DynarecCacheEntryState::Positive &&
		    entry.rip == rip && entry.compiled != nullptr)
		{
			return entry.compiled.get();
		}
	}
	return nullptr;
}

uint8_t X64A64DynarecFastBlockFlagsForTest(uint64_t rip)
{
	const size_t set_index = FastBlockCacheSet(rip);
	for (const auto& block: g_fast_blocks[set_index])
	{
		if (block.rip == rip) return block.vmovd_reg32_to_xmm;
	}
	return 0;
}

void X64PoisonA64DynarecDirectBlockBindingForTest(uint64_t rip)
{
	const size_t set_index = FastBlockCacheSet(rip);
	for (auto& block: g_fast_blocks[set_index])
	{
		if (block.rip != rip) continue;
		auto* binding = FastBlockA64DirectBindingFor(&block);
		if (binding == nullptr || binding->cache_owner_generation == 0) return;
		binding->entry_generation =
		    binding->entry_generation == UINT64_MAX
		        ? UINT64_C(1)
		        : binding->entry_generation + 1u;
		return;
	}
}

bool X64A64DynarecDirectBlockBindingPresentForTest(uint64_t rip)
{
	const size_t set_index = FastBlockCacheSet(rip);
	for (auto& block: g_fast_blocks[set_index])
	{
		if (block.rip != rip) continue;
		auto* binding = FastBlockA64DirectBindingFor(&block);
		return binding != nullptr && binding->cache_owner_generation != 0 &&
		       binding->entry_generation != 0;
	}
	return false;
}

