			auto* result = reinterpret_cast<uint32_t*>(s->xmm[source1]);
			for (uint8_t i = 0; i < qwords * 2; i++) result[i] = count >= 32 ? 0 : source[i] >> count;
			if (qwords == 2) s->xmm[source1][2] = s->xmm[source1][3] = 0;
